/**
 * Fångar profilen när en dialog öppnas, så att resultatet bara används om samma profil
 * fortfarande är laddad när den stängs. Modala dialoger låter EDT köra vidare, så ett
 * profilbyte (t.ex. utloggning och inloggning på ett annat konto) kan hinna ske medan
 * dialogen är öppen; då skulle målen annars hamna i fel konto.
 */
public final class ProfileGuard
{
	private final GoalManager goalManager;
	@Nullable
	private final String profileKey;

	private ProfileGuard(GoalManager goalManager)
	{
		this.goalManager = goalManager;
		this.profileKey = goalManager.getProfileKey();
	}

	public static ProfileGuard of(GoalManager goalManager)
	{
		return new ProfileGuard(goalManager);
	}

	/**
	 * @return true om samma profil fortfarande är laddad och går att ändra
	 */
	public boolean isCurrent()
	{
		return goalManager.isEditable() && Objects.equals(profileKey, goalManager.getProfileKey());
	}
}

