		TOTAL_LEVEL("Total level"),
		COMBAT_LEVEL("Combat level"),
		QUEST_POINTS("Quest points"),
		KILL_COUNT("Kill count");

		boolean isAccountLevel()
		{
			return this == TOTAL_LEVEL || this == COMBAT_LEVEL || this == QUEST_POINTS;
		}

