package com.gielinorgoals;

import com.gielinorgoals.model.ActivityCounters;
import com.gielinorgoals.model.DropSource;
import com.gielinorgoals.model.GameData;
import com.gielinorgoals.model.Goal;
import com.gielinorgoals.model.ItemRequirement;
import com.gielinorgoals.model.KillCountRequirement;
import com.gielinorgoals.tracking.InitialSync;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.hiscore.HiscoreSkill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class GoalManagerKillCountTest
{
	private static final String PROFILE = "profile";
	private static final String ZULRAH = "hiscore:ZULRAH";

	private long now = 1_000_000L;
	private final Map<String, String> stored = new HashMap<>();
	private final List<List<Goal>> announced = new ArrayList<>();
	private InitialSync initialSync;
	private GoalManager manager;

	@Before
	public void setUp()
	{
		initialSync = new InitialSync(() -> now);
		manager = new GoalManager(new GoalManager.Storage()
		{
			@Override
			public String get(String profileKey, String key)
			{
				return stored.get(profileKey + "." + key);
			}

			@Override
			public void set(String profileKey, String key, String value)
			{
				stored.put(profileKey + "." + key, value);
			}
		}, new Gson(), initialSync);
		manager.setCompletionListener(announced::add);
		manager.loadProfile(PROFILE);
	}

	@Test
	public void chatCountCompletesGoalWithPopup()
	{
		Goal goal = addGoal(KillCountRequirement.hiscore(HiscoreSkill.ZULRAH, 100));

		manager.recordChatCount(PROFILE, ZULRAH, 99);
		assertFalse(goal.isCompleted());
		assertEquals("99 / 100 kc", manager.getProgress(goal.getId()).getLabel());

		manager.recordChatCount(PROFILE, ZULRAH, 100);
		assertTrue(goal.isCompleted());
		assertFalse(goal.isCompletedAtApprox());
		assertEquals(List.of(List.of(goal)), announced);
	}

	@Test
	public void twoGoalsOnSameBossShareTheCounter()
	{
		Goal first = addGoal(KillCountRequirement.hiscore(HiscoreSkill.ZULRAH, 50));
		Goal second = addGoal(KillCountRequirement.hiscore(HiscoreSkill.ZULRAH, 200));

		manager.recordChatCount(PROFILE, ZULRAH, 120);

		assertTrue(first.isCompleted());
		assertEquals("120 / 200 kc", manager.getProgress(second.getId()).getLabel());
		assertEquals(1, manager.getCounters().asMap().size());
	}

	@Test
	public void hiscoresFillUnknownButNeverLowerAChatValue()
	{
		Goal goal = addGoal(KillCountRequirement.hiscore(HiscoreSkill.ZULRAH, 500));

		manager.recordHiscores(PROFILE, Map.of(ZULRAH, 300L, "hiscore:VORKATH", 40L));
		assertEquals("300 / 500 kc", manager.getProgress(goal.getId()).getLabel());

		manager.recordChatCount(PROFILE, ZULRAH, 320);
		manager.recordHiscores(PROFILE, Map.of(ZULRAH, 310L));
		assertEquals("320 / 500 kc", manager.getProgress(goal.getId()).getLabel());
		assertEquals(ActivityCounters.Source.CHAT, manager.getCounters().get(ZULRAH).getSource());
	}

	@Test
	public void npcLootCountsOnlyWatchedNpcsIgnoringCase()
	{
		Goal goal = addGoal(KillCountRequirement.npc("Lizardman shaman", 2));

		manager.recordNpcKill(PROFILE, "Goblin");
		manager.recordNpcKill(PROFILE, "LIZARDMAN SHAMAN");
		assertEquals("1 / 2 kc", manager.getProgress(goal.getId()).getLabel());
		manager.recordNpcKill(PROFILE, "Lizardman shaman");

		assertTrue(goal.isCompleted());
		// Ingen räknare skapas för NPC:er utan mål.
		assertEquals(-1, manager.getCounters().value("npc:goblin"));
	}

	@Test
	public void eventsForAnotherProfileAreIgnored()
	{
		Goal goal = addGoal(KillCountRequirement.hiscore(HiscoreSkill.ZULRAH, 1));

		manager.recordChatCount("other", ZULRAH, 5);

		assertFalse(goal.isCompleted());
		assertEquals(-1, manager.getCounters().value(ZULRAH));
	}

	@Test
	public void countsInFirstSyncAreQuietAndApprox()
	{
		Goal goal = addGoal(KillCountRequirement.hiscore(HiscoreSkill.ZULRAH, 10));
		initialSync.start();

		manager.recordHiscores(PROFILE, Map.of(ZULRAH, 50L));

		assertTrue(goal.isCompleted());
		assertTrue(goal.isCompletedAtApprox());
	}

	@Test
	public void manualCounterWorksWithoutGameDataAndIsSaved()
	{
		Goal goal = addGoal(KillCountRequirement.manual("Birdhouse runs", 3));
		String key = ((KillCountRequirement) goal.getRequirement()).counterKey();

		manager.adjustCounter(key, 1);
		manager.adjustCounter(key, 1);
		manager.setCounter(key, 2);
		assertFalse(goal.isCompleted());
		manager.adjustCounter(key, 1);
		assertTrue(goal.isCompleted());

		manager.loadProfile(PROFILE);
		assertEquals(3, manager.getCounters().value(key));
		assertEquals(ActivityCounters.Source.MANUAL, manager.getCounters().get(key).getSource());
	}

	@Test
	public void killCountIsSavedWhenAnItemGoalWithDropSourceIsCompleted()
	{
		manager.addGoal(null, "", null, new ItemRequirement(FANG, "Tanzanite fang", 1, false), false,
			DropSource.hiscore(HiscoreSkill.ZULRAH, 1024));
		Goal fang = lastRoot();
		manager.recordChatCount(PROFILE, ZULRAH, 1240);
		assertNull(fang.getObtainedAtKc());

		// Föremålet syns i inventory: målet klaras av sig självt och KC sparas.
		manager.updateGameData(PROFILE, fang(1));

		assertTrue(fang.isCompleted());
		assertEquals(Long.valueOf(1240L), fang.getObtainedAtKc());
		// Räknaren fortsätter, men det sparade värdet är kvar.
		manager.recordChatCount(PROFILE, ZULRAH, 1300);
		assertEquals(Long.valueOf(1240L), fang.getObtainedAtKc());
		manager.loadProfile(PROFILE);
		assertEquals(Long.valueOf(1240L), lastRoot().getObtainedAtKc());
	}

	@Test
	public void manualCompletionAlsoSavesTheKillCountAndUndoForgetsIt()
	{
		manager.addGoal(null, "", null, new ItemRequirement(FANG, "Tanzanite fang", 1, false), false,
			DropSource.hiscore(HiscoreSkill.ZULRAH, 1024));
		Goal fang = lastRoot();
		manager.recordChatCount(PROFILE, ZULRAH, 77);

		manager.setCompleted(fang.getId(), true);
		assertEquals(Long.valueOf(77L), fang.getObtainedAtKc());

		manager.setCompleted(fang.getId(), false);
		assertNull(fang.getObtainedAtKc());
	}

	@Test
	public void npcDropSourceIsWatchedSoLootCounts()
	{
		manager.addGoal(null, "", null, new ItemRequirement(DWH, "Dragon warhammer", 1, false), false,
			DropSource.npc("Lizardman shaman", 5000));

		manager.recordNpcKill(PROFILE, "Lizardman shaman");

		assertEquals(1, manager.getCounters().value("npc:lizardman shaman"));
		assertTrue(manager.watchedCounterKeys().contains("npc:lizardman shaman"));
	}

	@Test
	public void dropSourceOnlyStaysOnItemGoals()
	{
		manager.addGoal(null, "Kill Zulrah", null, null, false, DropSource.hiscore(HiscoreSkill.ZULRAH, 5000));

		assertNull(lastRoot().getDropSource());
	}

	private static final int FANG = 12922;
	private static final int DWH = 13576;

	private static GameData fang(long count)
	{
		return new GameData()
		{
			@Override
			public long getXp(net.runelite.api.Skill skill)
			{
				return 0;
			}

			@Override
			public long getItemCount(int itemId)
			{
				return itemId == FANG ? count : 0;
			}
		};
	}

	private Goal lastRoot()
	{
		List<Goal> roots = manager.getTree().getRoots();
		return roots.get(roots.size() - 1);
	}

	private Goal addGoal(KillCountRequirement requirement)
	{
		manager.addGoal(null, "", null, requirement);
		List<Goal> roots = manager.getTree().getRoots();
		return roots.get(roots.size() - 1);
	}
}

package com.gielinorgoals;

import com.gielinorgoals.template.QuestRequirementsDb;
import com.gielinorgoals.template.TemplateUpdates;
import com.gielinorgoals.template.TemplateCatalog;
import com.gielinorgoals.model.GameData;
import com.gielinorgoals.model.Goal;
import com.gielinorgoals.model.QuestRequirement;
import com.gielinorgoals.model.Requirement;
import com.gielinorgoals.template.QuestCapeExclusions;
import com.gielinorgoals.template.QuestCapeTemplate;
import com.gielinorgoals.template.TemplateInserter;
import com.gielinorgoals.template.TemplateNode;
import com.gielinorgoals.tracking.InitialSync;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class GoalManagerTemplateTest
{
	private static final String PROFILE = "profile";

	private final List<List<Goal>> announced = new ArrayList<>();
	private final Map<String, String> stored = new java.util.HashMap<>();
	private int goalSaves;
	private int rebuilds;
	private GoalManager manager;

	@Before
	public void setUp()
	{
		manager = new GoalManager(new GoalManager.Storage()
		{
			@Override
			public String get(String profileKey, String key)
			{
				return stored.get(profileKey + "." + key);
			}

			@Override
			public void set(String profileKey, String key, String value)
			{
				stored.put(profileKey + "." + key, value);
				if (key.equals("goals"))
				{
					goalSaves++;
				}
			}
		}, new Gson(), new InitialSync(() -> 0L));
		manager.setCompletionListener(announced::add);
		manager.setListener(() -> rebuilds++);
		manager.loadProfile(PROFILE);
	}

	@Test
	public void finishedQuestsAreCompletedQuietlyWithApproxDates()
	{
		TemplateNode cape = new QuestCapeTemplate(QuestCapeExclusions.load(new Gson())).build(Map.of());
		Set<Integer> finished = new HashSet<>();
		// Alla quests utom de tre första är klara, som för en spelare med många quests.
		for (int i = 3; i < cape.getChildren().size(); i++)
		{
			finished.add(questId(cape.getChildren().get(i).getRequirement()));
		}
		manager.updateGameData(PROFILE, quests(finished));
		goalSaves = 0;
		rebuilds = 0;

		TemplateInserter.Result result = manager.insertTemplate(cape);

		assertEquals(finished.size(), result.countCompleted());
		for (Goal goal : result.getCreated())
		{
			if (goal.getRequirement() != null && finished.contains(questId(goal.getRequirement())))
			{
				assertTrue(goal.isCompleted());
				assertTrue(goal.isCompletedAtApprox());
			}
		}
		assertFalse(result.getRoot().isCompleted());
		// Ingen popup eller chattmeddelande, och allt i en sparning och en ombyggnad.
		assertTrue(announced.isEmpty());
		assertEquals(1, goalSaves);
		assertEquals(1, rebuilds);
	}

	@Test
	public void templateThatIsAlreadyDoneCompletesQuietly()
	{
		TemplateNode cape = TemplateNode.aggregate("Two quests")
			.add(TemplateNode.requirement(new QuestRequirement(17, "Cook's Assistant")))
			.add(TemplateNode.requirement(new QuestRequirement(25, "Demon Slayer")));
		manager.updateGameData(PROFILE, quests(Set.of(17, 25)));

		TemplateInserter.Result result = manager.insertTemplate(cape);

		// Även räknarmålet blir klart, tyst och med ungefärligt datum.
		assertTrue(result.getRoot().isCompleted());
		assertTrue(result.getRoot().isCompletedAtApprox());
		assertTrue(announced.isEmpty());
	}

	@Test
	public void questCompletedAfterInsertGivesNormalPopup()
	{
		TemplateNode cape = TemplateNode.aggregate("Two quests")
			.add(TemplateNode.requirement(new QuestRequirement(17, "Cook's Assistant")))
			.add(TemplateNode.requirement(new QuestRequirement(25, "Demon Slayer")));
		manager.updateGameData(PROFILE, quests(Set.of(17)));
		manager.insertTemplate(cape);

		manager.updateGameData(PROFILE, quests(Set.of(17, 25)));

		// Demon Slayer och kappan klarades nu: en vanlig batch med exakt datum.
		assertEquals(1, announced.size());
		assertEquals(2, announced.get(0).size());
		assertFalse(announced.get(0).get(0).isCompletedAtApprox());
	}

	@Test
	public void insertedTemplateSurvivesReload()
	{
		manager.insertTemplate(new QuestCapeTemplate(QuestCapeExclusions.load(new Gson())).build(Map.of()));
		int size = manager.getTree().size();

		manager.loadProfile(PROFILE);

		assertEquals(size, manager.getTree().size());
		assertEquals("Quest cape", manager.getTree().getRoots().get(0).getTitle());
		assertTrue(manager.getTree().getRoots().get(0).isAggregate());
	}

	private static int questId(@Nullable Requirement requirement)
	{
		return ((QuestRequirement) requirement).getQuestId();
	}

	private static GameData quests(Set<Integer> finished)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public QuestState getQuestState(int questId)
			{
				return finished.contains(questId) ? QuestState.FINISHED : QuestState.NOT_STARTED;
			}
		};
	}

	@Test
	public void updateFromTemplateRestoresDeletedGoalsInOneSave()
	{
		TemplateCatalog catalog = new TemplateCatalog(new Gson());
		TemplateUpdates updates = new TemplateUpdates(catalog, QuestRequirementsDb.load(new Gson()));
		TemplateNode node = catalog.find("base-level").build(Map.of("level", 60));
		node.setTemplateId("base-level");
		node.setTemplateParams(Map.of("level", 60));
		Goal root = manager.insertTemplate(node).getRoot();
		Goal attack = manager.getTree().getChildren(root).get(0);
		manager.removeGoal(attack.getId());
		int size = manager.getTree().size();

		TemplateUpdates.Plan plan = updates.plan(manager.getTree(), root);
		assertEquals(1, plan.getAdditions().size());
		goalSaves = 0;
		rebuilds = 0;
		manager.applyTemplateUpdate(root.getId(), plan.getAdditions(), List.of(), List.of());

		assertEquals(size + 1, manager.getTree().size());
		assertTrue(updates.plan(manager.getTree(), root).isEmpty());
		assertEquals(1, goalSaves);
		assertEquals(1, rebuilds);
		assertTrue(announced.isEmpty());
	}

	@Test
	public void declinedAdditionsAreNotSuggestedAgain()
	{
		TemplateCatalog catalog = new TemplateCatalog(new Gson());
		TemplateUpdates updates = new TemplateUpdates(catalog, QuestRequirementsDb.load(new Gson()));
		TemplateNode node = catalog.find("base-level").build(Map.of());
		node.setTemplateId("base-level");
		node.setTemplateParams(Map.of());
		Goal root = manager.insertTemplate(node).getRoot();
		Goal attack = manager.getTree().getChildren(root).get(0);
		manager.removeGoal(attack.getId());

		TemplateUpdates.Plan plan = updates.plan(manager.getTree(), root);
		manager.applyTemplateUpdate(root.getId(), List.of(), List.of(),
			List.of(plan.getAdditions().get(0).getNode().getKey()));

		assertTrue(updates.plan(manager.getTree(), root).isEmpty());
	}

	@Test
	public void removedNodeSharedWithAnotherGoalIsOnlyUnlinked()
	{
		manager.addGoal(null, "Elsewhere", null, null);
		Goal elsewhere = manager.getTree().getRoots().get(0);
		TemplateCatalog catalog = new TemplateCatalog(new Gson());
		TemplateNode node = catalog.find("base-level").build(Map.of());
		node.setTemplateId("base-level");
		node.setTemplateParams(Map.of());
		Goal root = manager.insertTemplate(node).getRoot();
		Goal attack = manager.getTree().getChildren(root).get(0);
		Goal defence = manager.getTree().getChildren(root).get(1);
		manager.link(elsewhere.getId(), attack.getId());

		manager.applyTemplateUpdate(root.getId(), List.of(), List.of(attack.getId(), defence.getId()), List.of());

		// Attack finns kvar under det andra målet; Defence fanns bara i templaten och tas bort.
		assertEquals(List.of(elsewhere), manager.getTree().getParents(attack.getId()));
		assertEquals(null, manager.getTree().find(defence.getId()));
	}
}

package com.gielinorgoals;

import com.gielinorgoals.model.GameData;
import com.gielinorgoals.model.Goal;
import com.gielinorgoals.model.SkillRequirement;
import com.gielinorgoals.tracking.InitialSync;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class GoalManagerTest
{
	private static final String PROFILE = "profile";

	private long now = 1_000_000L;
	private final Map<String, String> stored = new HashMap<>();
	private final List<List<Goal>> announced = new ArrayList<>();
	private InitialSync initialSync;
	private GoalManager manager;

	@Before
	public void setUp()
	{
		initialSync = new InitialSync(() -> now);
		manager = new GoalManager(new GoalManager.Storage()
		{
			@Override
			public String get(String profileKey, String key)
			{
				return stored.get(profileKey + "." + key);
			}

			@Override
			public void set(String profileKey, String key, String value)
			{
				stored.put(profileKey + "." + key, value);
			}
		}, new Gson(), initialSync);
		manager.setCompletionListener(announced::add);
		manager.loadProfile(PROFILE);
	}

	@Test
	public void goalMetInFirstSyncAfterLoginGetsApproxDate()
	{
		Goal goal = addCookingGoal();

		initialSync.start();
		manager.updateGameData(PROFILE, cookingXp(1_000_000));

		assertTrue(goal.isCompleted());
		assertTrue(goal.isCompletedAtApprox());
	}

	@Test
	public void goalMetAfterFirstSyncGetsExactDate()
	{
		Goal goal = addCookingGoal();
		manager.updateGameData(PROFILE, cookingXp(0));

		initialSync.start();
		now += InitialSync.WINDOW_MS;
		manager.updateGameData(PROFILE, cookingXp(1_000_000));

		assertTrue(goal.isCompleted());
		assertFalse(goal.isCompletedAtApprox());
		assertEquals(1, announced.size());
	}

	@Test
	public void goalAlreadyMetWhenAddedGetsApproxDate()
	{
		manager.updateGameData(PROFILE, cookingXp(1_000_000));

		Goal goal = addCookingGoal();

		assertTrue(goal.isCompleted());
		assertTrue(goal.isCompletedAtApprox());
		assertTrue(announced.isEmpty());
	}

	@Test
	public void goalMetWhileOfflineIsApproxAfterProfileLoad()
	{
		addCookingGoal();
		manager.updateGameData(PROFILE, cookingXp(1));
		manager.unload();

		// Samma profil laddas igen när datan redan visar att målet är nått.
		manager.updateGameData(PROFILE, cookingXp(1_000_000));
		manager.loadProfile(PROFILE);

		Goal reloaded = manager.getTree().getRoots().get(0);
		assertTrue(reloaded.isCompleted());
		assertTrue(reloaded.isCompletedAtApprox());
	}

	@Test
	public void manualTickIsExactAndUntickResetsDate()
	{
		manager.addGoal(null, "Fire cape", null, null);
		Goal goal = manager.getTree().getRoots().get(0);

		manager.setCompleted(goal.getId(), true);
		assertFalse(goal.isCompletedAtApprox());
		assertNotNull(goal.getCompletedAt());

		goal.setCompletedAtApprox(true);
		manager.setCompleted(goal.getId(), false);
		assertNull(goal.getCompletedAt());
		assertFalse(goal.isCompletedAtApprox());
	}

	@Test
	public void newGoalsGetCreatedAtAndSurviveReload()
	{
		manager.addGoal(null, "Fire cape", null, null);
		Long createdAt = manager.getTree().getRoots().get(0).getCreatedAt();

		manager.loadProfile(PROFILE);

		assertEquals(createdAt, manager.getTree().getRoots().get(0).getCreatedAt());
	}

	@Test
	public void collapseAllCollapsesEveryGoalWithSubGoalsInOneSave()
	{
		manager.addGoal(null, "Parent", null, null);
		Goal parent = manager.getTree().getRoots().get(0);
		manager.addGoal(parent.getId(), "Child", null, null);
		Goal child = manager.getTree().getChildren(parent).get(0);
		manager.addGoal(child.getId(), "Grandchild", null, null);
		manager.addGoal(null, "Leaf", null, null);
		Goal leaf = manager.getTree().getRoots().get(1);
		assertTrue(parent.isExpanded());
		assertTrue(child.isExpanded());
		String before = stored.get(PROFILE + ".goals");

		manager.collapseAll();

		assertFalse(parent.isExpanded());
		assertFalse(child.isExpanded());
		// Ett mål utan delmål rörs inte; det har ingen fäll-knapp.
		assertTrue(leaf.isExpanded());
		assertFalse(before.equals(stored.get(PROFILE + ".goals")));
		manager.loadProfile(PROFILE);
		assertFalse(manager.getTree().find(parent.getId()).isExpanded());
	}

	@Test
	public void revealExpandsCollapsedAncestors()
	{
		manager.addGoal(null, "Parent", null, null);
		Goal parent = manager.getTree().getRoots().get(0);
		manager.addGoal(parent.getId(), "Child", null, null);
		Goal child = manager.getTree().getChildren(parent).get(0);
		manager.toggleExpanded(parent.getId());
		assertFalse(parent.isExpanded());

		assertTrue(manager.reveal(child.getId()));

		assertTrue(parent.isExpanded());
		assertFalse(manager.reveal("missing"));
	}

	private Goal addCookingGoal()
	{
		manager.addGoal(null, "", null, SkillRequirement.level(Skill.COOKING, 70));
		return manager.getTree().getRoots().get(manager.getTree().getRoots().size() - 1);
	}

	private static GameData cookingXp(long xp)
	{
		return skill -> skill == Skill.COOKING ? xp : 0;
	}

	@Test
	public void showAsCounterCollapsesAndIsSaved()
	{
		manager.addGoal(null, "Quest cape", null, null);
		Goal cape = manager.getTree().getRoots().get(0);
		assertTrue(cape.isExpanded());

		manager.setAggregate(cape.getId(), true);

		assertTrue(cape.isAggregate());
		assertFalse(cape.isExpanded());
		manager.loadProfile(PROFILE);
		assertTrue(manager.getTree().getRoots().get(0).isAggregate());
	}

	@Test
	public void tickingLastSubGoalCompletesCounterWithPopupAndExactDate()
	{
		manager.addGoal(null, "Quest cape", null, null, true);
		Goal cape = manager.getTree().getRoots().get(0);
		manager.addGoal(cape.getId(), "Quest 1", null, null);
		manager.addGoal(cape.getId(), "Quest 2", null, null);
		List<Goal> quests = manager.getTree().getChildren(cape);

		manager.setCompleted(quests.get(0).getId(), true);
		assertFalse(cape.isCompleted());
		assertEquals("1/2", manager.getProgress(cape.getId()).getLabel());

		// Utan speldata, eftersom räknaren bara beror på delmålen.
		manager.setCompleted(quests.get(1).getId(), true);

		assertTrue(cape.isCompleted());
		assertFalse(cape.isCompletedAtApprox());
		assertEquals(List.of(List.of(cape)), announced);
	}

	@Test
	public void linkAndUnlinkAreSavedAndCyclesRefused()
	{
		manager.addGoal(null, "Barrows gloves", null, null);
		manager.addGoal(null, "Quest cape", null, null);
		Goal gloves = manager.getTree().getRoots().get(0);
		Goal cape = manager.getTree().getRoots().get(1);
		manager.addGoal(gloves.getId(), "Recipe for Disaster", null, null);
		Goal rfd = manager.getTree().getChildren(gloves).get(0);

		manager.link(cape.getId(), rfd.getId());
		manager.link(rfd.getId(), gloves.getId());
		manager.loadProfile(PROFILE);

		assertEquals(2, manager.getTree().getParents(rfd.getId()).size());
		assertTrue(manager.getTree().getChildren(manager.getTree().find(rfd.getId())).isEmpty());

		manager.unlink(gloves.getId(), rfd.getId());
		manager.loadProfile(PROFILE);
		assertEquals(List.of(cape.getId()),
			List.of(manager.getTree().getParents(rfd.getId()).get(0).getId()));
	}
}

