import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Test;

public class QuestRequirementsDbTest
{
	private final QuestRequirementsDb db = QuestRequirementsDb.load(new Gson());
	private final Map<Integer, String> enumNames = new HashMap<>();

	{
		for (Quest quest : Quest.values())
		{
			enumNames.put(quest.getId(), quest.getName());
		}
	}

	@Test
	public void priorityChainsAreLoaded()
	{
		for (Quest quest : new Quest[]{Quest.SONG_OF_THE_ELVES, Quest.RECIPE_FOR_DISASTER, Quest.DRAGON_SLAYER_II,
			Quest.DESERT_TREASURE_I, Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE, Quest.MONKEY_MADNESS_II})
		{
			assertNotNull(quest.getName(), db.get(quest.getId()));
		}
		assertEquals(Integer.valueOf(175), db.get(Quest.RECIPE_FOR_DISASTER.getId()).getQuestPoints());
	}

	@Test
	public void everyReferencePointsAtAnExistingQuestWithTheSameName()
	{
		for (QuestRequirementsDb.Entry entry : db.all().values())
		{
			assertEquals("entry " + entry.getId(), enumNames.get(entry.getId()), entry.getName());
			for (QuestRequirementsDb.Ref ref : entry.getQuests())
			{
				assertEquals(entry.getName() + " -> " + ref.getName(), enumNames.get(ref.getId()), ref.getName());
			}
			for (QuestRequirementsDb.Partial partial : entry.getPartial())
			{
				assertEquals(entry.getName() + " partial", enumNames.get(partial.getId()), partial.getName());
				assertTrue(partial.getText() != null && !partial.getText().isEmpty());
			}
		}
	}

	@Test
	public void everyPrerequisiteHasItsOwnEntry()
	{
		// Kedjorna ska kunna fällas ut hela vägen för de quests som finns i filen.
		List<String> missing = new ArrayList<>();
		for (QuestRequirementsDb.Entry entry : db.all().values())
		{
			for (QuestRequirementsDb.Ref ref : entry.getQuests())
			{
				if (db.get(ref.getId()) == null)
				{
					missing.add(entry.getName() + " -> " + ref.getName());
				}
			}
		}
		assertTrue("Prerequisites without an entry: " + missing, missing.isEmpty());
	}

	@Test
	public void skillNamesAndLevelsAreValid()
	{
		for (QuestRequirementsDb.Entry entry : db.all().values())
		{
			for (QuestRequirementsDb.SkillReq req : entry.getSkills())
			{
				try
				{
					Skill.valueOf(req.getSkill());
				}
				catch (IllegalArgumentException e)
				{
					fail(entry.getName() + " has unknown skill " + req.getSkill());
				}
				assertTrue(entry.getName() + " " + req.getSkill(), req.getLevel() >= 2 && req.getLevel() <= 99);
			}
		}
	}

	@Test
	public void thereAreNoCycles()
	{
		Set<Integer> done = new HashSet<>();
		for (int id : db.all().keySet())
		{
			visit(id, new HashSet<>(), done);
		}
	}

	private void visit(int id, Set<Integer> path, Set<Integer> done)
	{
		if (done.contains(id))
		{
			return;
		}
		if (!path.add(id))
		{
			fail("Cycle through " + enumNames.get(id));
		}
		QuestRequirementsDb.Entry entry = db.get(id);
		if (entry != null)
		{
			for (QuestRequirementsDb.Ref ref : entry.getQuests())
			{
				visit(ref.getId(), path, done);
			}
		}
		path.remove(id);
		done.add(id);
	}

	@Test
	public void questsMissingFromTheFileAreListedButDoNotFail()
	{
		List<String> missing = db.missingQuests();
		System.out.println("Quests without requirement data (" + missing.size() + " of " + Quest.values().length + "): "
			+ missing);
		assertNull(db.get(-12345));
	}
}

package com.gielinorgoals.template;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TemplateCategoriesTest
{
	private final List<GoalTemplate> templates = new TemplateCatalog(new Gson()).getTemplates();

	@Test
	public void existingTemplatesHaveTheirCategories()
	{
		Map<String, List<GoalTemplate>> grouped = TemplateCategories.group(templates, "", false);

		assertEquals(List.of(TemplateCategories.CAPES, TemplateCategories.IRONMAN_EARLY, TemplateCategories.IRONMAN_MID,
			TemplateCategories.IRONMAN_LATE, TemplateCategories.SKILLS), new ArrayList<>(grouped.keySet()));
		assertEquals(List.of("Quest cape", "Achievement diary cape"), names(grouped.get(TemplateCategories.CAPES)));
		assertEquals("Barrows gloves", names(grouped.get(TemplateCategories.IRONMAN_MID)).get(0));
		assertEquals(List.of("Base N"), names(grouped.get(TemplateCategories.SKILLS)));
	}

	@Test
	public void ironmanCategoriesComeFirstForIronmen()
	{
		Map<String, List<GoalTemplate>> grouped = TemplateCategories.group(templates, "", true);

		assertEquals(List.of(TemplateCategories.IRONMAN_EARLY, TemplateCategories.IRONMAN_MID,
			TemplateCategories.IRONMAN_LATE, TemplateCategories.CAPES, TemplateCategories.SKILLS),
			new ArrayList<>(grouped.keySet()));
	}

	@Test
	public void searchMatchesNamesAndTags()
	{
		assertEquals(List.of("Barrows gloves"), names(flat(TemplateCategories.group(templates, "rfd", false))));
		assertEquals(List.of("Quest cape", "Barrows gloves"),
			names(flat(TemplateCategories.group(templates, "QUEST", false))));
		assertEquals(List.of("Base N"), names(flat(TemplateCategories.group(templates, "base", false))));
		assertTrue(TemplateCategories.group(templates, "nothing like this", false).isEmpty());
	}

	@Test
	public void unknownCategoryEndsUpInOther()
	{
		JsonTemplate.FileSpec spec = new Gson().fromJson("{\"name\":\"Odd\",\"category\":\"Typo\","
			+ "\"root\":{\"title\":\"Root\"}}", JsonTemplate.FileSpec.class);
		Map<String, List<GoalTemplate>> grouped = TemplateCategories.group(List.of(JsonTemplate.from(spec)), "", false);

		assertEquals(List.of(TemplateCategories.OTHER), new ArrayList<>(grouped.keySet()));
	}

	@Test
	public void jsonNodesCanHaveTheirOwnWikiPage()
	{
		JsonTemplate.FileSpec spec = new Gson().fromJson("{\"name\":\"Wiki\",\"root\":{\"title\":\"Root\","
			+ "\"wikiPage\":\"Culinaromancer's Chest\"}}", JsonTemplate.FileSpec.class);

		assertEquals("Culinaromancer's Chest", JsonTemplate.from(spec).build(Map.of()).getWikiPage());
	}

	private static List<GoalTemplate> flat(Map<String, List<GoalTemplate>> grouped)
	{
		List<GoalTemplate> all = new ArrayList<>();
		grouped.values().forEach(all::addAll);
		return all;
	}

	private static List<String> names(List<GoalTemplate> templates)
	{
		List<String> names = new ArrayList<>();
		templates.forEach(template -> names.add(template.getName()));
		return names;
	}
}

package com.gielinorgoals.template;

import com.gielinorgoals.model.DiaryArea;
import com.gielinorgoals.model.DiaryRequirement;
import com.gielinorgoals.model.DiaryTier;
import com.gielinorgoals.model.QuestRequirement;
import com.gielinorgoals.model.SkillRequirement;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TemplateGenerationTest
{
	private final QuestCapeExclusions exclusions = QuestCapeExclusions.load(new Gson());

	@Test
	public void everyExcludedNameExistsInTheQuestEnum() throws Exception
	{
		JsonObject raw;
		try (InputStreamReader in = new InputStreamReader(
			QuestCapeExclusions.class.getResourceAsStream(QuestCapeExclusions.RESOURCE), StandardCharsets.UTF_8))
		{
			raw = new Gson().fromJson(in, JsonObject.class);
		}

		// Ett namn som RuneLite har bytt skulle tyst hoppas över; här märks det.
		assertEquals(raw.getAsJsonArray("miniquests").size(), exclusions.getMiniquests().size());
		assertEquals(raw.getAsJsonArray("subquests").size(), exclusions.getSubquests().size());
		assertEquals(19, exclusions.getMiniquests().size());
		assertEquals(10, exclusions.getSubquests().size());
	}

	@Test
	public void questCapeSkipsMiniquestsAndRecipeForDisasterParts()
	{
		TemplateNode cape = new QuestCapeTemplate(exclusions).build(Map.of());

		assertTrue(cape.isAggregate());
		assertEquals("Quest cape", cape.getTitle());
		int expected = Quest.values().length - exclusions.getMiniquests().size() - exclusions.getSubquests().size();
		assertEquals(expected, cape.getChildren().size());

		Set<Integer> ids = questIds(cape);
		assertTrue(ids.contains(Quest.RECIPE_FOR_DISASTER.getId()));
		assertFalse(ids.contains(Quest.RECIPE_FOR_DISASTER__CULINAROMANCER.getId()));
		assertFalse(ids.contains(Quest.MAGE_ARENA_I.getId()));
		assertFalse(ids.contains(Quest.ALFRED_GRIMHANDS_BARCRAWL.getId()));
		// Bone Voyage låter som en miniquest men är en quest.
		assertTrue(ids.contains(Quest.BONE_VOYAGE.getId()));
		assertEquals(cape.getChildren().size(), ids.size());
	}

	@Test
	public void questCapeWithoutExclusionsHasEveryQuest()
	{
		TemplateNode cape = new QuestCapeTemplate(QuestCapeExclusions.none()).build(Map.of());

		assertEquals(Quest.values().length, cape.getChildren().size());
	}

	@Test
	public void diaryCapeHasFourTiersInTwelveAreas()
	{
		TemplateNode cape = new DiaryCapeTemplate().build(Map.of());

		assertEquals(12, DiaryArea.values().length);
		assertEquals(DiaryArea.values().length, cape.getChildren().size());
		for (int i = 0; i < DiaryArea.values().length; i++)
		{
			TemplateNode area = cape.getChildren().get(i);
			assertTrue(area.isAggregate());
			assertEquals(DiaryTier.values().length, area.getChildren().size());
			for (int t = 0; t < DiaryTier.values().length; t++)
			{
				assertEquals(new DiaryRequirement(DiaryArea.values()[i], DiaryTier.values()[t]),
					area.getChildren().get(t).getRequirement());
			}
		}
		assertEquals(1 + 12 + 12 * 4, cape.size());
	}

	@SuppressWarnings("deprecation")
	@Test
	public void baseLevelHasOneGoalPerSkillWithoutOverall()
	{
		BaseLevelTemplate template = new BaseLevelTemplate();

		TemplateNode base70 = template.build(Map.of());
		assertEquals("Base 70", base70.getTitle());
		// OVERALL finns inte alltid i Skill.values(), så räkna de riktiga skillsen.
		long realSkills = java.util.Arrays.stream(Skill.values()).filter(skill -> skill != Skill.OVERALL).count();
		assertEquals(realSkills, base70.getChildren().size());
		Set<Skill> skills = new HashSet<>();
		for (TemplateNode node : base70.getChildren())
		{
			SkillRequirement requirement = (SkillRequirement) node.getRequirement();
			assertEquals(SkillRequirement.Mode.LEVEL, requirement.getMode());
			assertEquals(70, requirement.getTarget());
			skills.add(requirement.getSkill());
		}
		assertFalse(skills.contains(Skill.OVERALL));
		assertTrue(skills.contains(Skill.SAILING));

		assertEquals("Base 99", template.build(Map.of("level", 99)).getTitle());
		// Utanför gränserna klampas värdet.
		assertEquals("Base 99", template.build(Map.of("level", 150)).getTitle());
		assertEquals("Base 2", template.build(Map.of("level", 1)).getTitle());
	}

	@Test
	public void everyBuildGivesAFreshTree()
	{
		QuestCapeTemplate template = new QuestCapeTemplate(exclusions);
		TemplateNode first = template.build(Map.of());
		first.getChildren().get(0).setIncluded(false);

		assertTrue(template.build(Map.of()).getChildren().get(0).isIncluded());
	}

	private static Set<Integer> questIds(TemplateNode cape)
	{
		Set<Integer> ids = new HashSet<>();
		for (TemplateNode node : cape.getChildren())
		{
			ids.add(((QuestRequirement) node.getRequirement()).getQuestId());
		}
		return ids;
	}
}

package com.gielinorgoals.template;

import com.gielinorgoals.model.GoalIcon;
import com.google.gson.Gson;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import net.runelite.api.gameval.ItemID;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Item-ikonerna i templaten ska vara riktiga föremål. Ett felskrivet id syns annars bara
 * som en tom ikon. Listan nedan är gameval-konstanterna för de ikoner som används; en ny
 * ikon läggs till här med sin konstant.
 */
public class TemplateIconIdsTest
{
	private static final Set<Integer> KNOWN_ICONS = Set.of(
		ItemID.BOW_OF_FAERDHINEN,
		ItemID.DRAGON_WARHAMMER,
		ItemID.XERIC_TALISMAN,
		ItemID.TZHAAR_CAPE_FIRE,
		ItemID.INFERNAL_CAPE,
		ItemID.DRAGON_PARRYINGDAGGER,
		ItemID.BARBASSAULT_PENANCE_FIGHTER_TORSO,
		ItemID.AVAS_ASSEMBLER,
		ItemID.GRACEFUL_TOP,
		ItemID.GRACE,
		ItemID.BH_RUNE_POUCH,
		ItemID.MA2_SARADOMIN_CAPE,
		ItemID.ZENYTE_AMULET_ENCHANTED,
		ItemID.ZENYTE,
		ItemID.ARDY_CAPE_ELITE,
		ItemID.DRAMEN_STAFF,
		ItemID.SKILLCAPE_QP,
		ItemID.SKILLCAPE_AD);

	@Test
	public void everyItemIconIsAKnownGamevalItem()
	{
		Set<Integer> used = new TreeSet<>();
		for (GoalTemplate template : new TemplateCatalog(new Gson()).getTemplates())
		{
			if (template.getIcon() != null && template.getIcon().getItemId() != null)
			{
				used.add(template.getIcon().getItemId());
			}
			collect(template.build(Map.of("level", 70)), used);
		}

		Set<Integer> unknown = new TreeSet<>(used);
		unknown.removeAll(KNOWN_ICONS);
		assertTrue("item icons without a known gameval constant: " + unknown, unknown.isEmpty());
		assertTrue("icons used: " + used, used.size() >= 15);
	}

	private static void collect(TemplateNode node, Set<Integer> out)
	{
		GoalIcon icon = node.getIcon();
		if (icon != null && icon.getItemId() != null)
		{
			out.add(icon.getItemId());
		}
		node.getChildren().forEach(child -> collect(child, out));
	}
}

package com.gielinorgoals.template;

import com.gielinorgoals.model.DiaryArea;
import com.gielinorgoals.model.DiaryRequirement;
import com.gielinorgoals.model.DiaryTier;
import com.gielinorgoals.model.Goal;
import com.gielinorgoals.model.GoalTree;
import com.gielinorgoals.model.QuestRequirement;
import com.gielinorgoals.model.SkillRequirement;
import java.util.List;
import java.util.Map;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TemplateInserterTest
{
	@Test
	public void exactMatchIsLinkedInsteadOfDuplicated()
	{
		GoalTree tree = new GoalTree();
		Goal cooks = new Goal("");
		// Annat sparat namn, samma quest-id: räknas som samma mål.
		cooks.setRequirement(new QuestRequirement(17, "Cook's Assistant (old name)"));
		tree.add(null, cooks);

		TemplateNode cape = TemplateNode.aggregate("Quest cape")
			.add(TemplateNode.requirement(new QuestRequirement(17, "Cook's Assistant")))
			.add(TemplateNode.requirement(new QuestRequirement(25, "Demon Slayer")));

		TemplateInserter.Result result = TemplateInserter.insert(tree, cape);

		assertEquals(List.of(cooks), result.getLinked());
		assertEquals(2, result.getCreated().size());
		// Det befintliga målet, kapan och Demon Slayer; ingen dubblett av Cook's Assistant.
		assertEquals(3, tree.size());
		Goal root = result.getRoot();
		assertEquals(List.of(cooks.getId(), result.getCreated().get(1).getId()), root.getChildIds());
		// Det befintliga målet är inte längre ett eget rotmål, utan ligger under kappan.
		assertEquals(List.of(root.getId()), tree.getRootIds());
		assertEquals(List.of(root), tree.getParents(cooks.getId()));
	}

	@Test
	public void nearMatchCreatesNewGoal()
	{
		GoalTree tree = new GoalTree();
		Goal attack80 = new Goal("");
		attack80.setRequirement(SkillRequirement.level(Skill.ATTACK, 80));
		tree.add(null, attack80);

		TemplateNode base = TemplateNode.aggregate("Base 85")
			.add(TemplateNode.requirement(SkillRequirement.level(Skill.ATTACK, 85)));

		TemplateInserter.Result result = TemplateInserter.insert(tree, base);

		assertTrue(result.getLinked().isEmpty());
		Goal attack85 = result.getCreated().get(1);
		assertNotSame(attack80, attack85);
		assertEquals(SkillRequirement.level(Skill.ATTACK, 85), attack85.getRequirement());
		assertTrue(tree.getParents(attack80.getId()).isEmpty());
	}

	@Test
	public void sharedGoalIsLinkedIntoSecondTemplate()
	{
		GoalTree tree = new GoalTree();
		TemplateInserter.Result gloves = TemplateInserter.insert(tree, TemplateNode.aggregate("Barrows gloves")
			.add(TemplateNode.requirement(new QuestRequirement(117, "Recipe for Disaster"))));
		Goal rfd = gloves.getCreated().get(1);

		TemplateInserter.Result cape = TemplateInserter.insert(tree, TemplateNode.aggregate("Quest cape")
			.add(TemplateNode.requirement(new QuestRequirement(117, "Recipe for Disaster"))));

		assertEquals(List.of(rfd), cape.getLinked());
		assertEquals(2, tree.getParents(rfd.getId()).size());
		assertEquals(3, tree.size());
	}

	@Test
	public void sameRequirementTwiceInOneTemplateGivesOneGoal()
	{
		GoalTree tree = new GoalTree();
		TemplateNode template = TemplateNode.aggregate("Root")
			.add(TemplateNode.aggregate("A").add(TemplateNode.requirement(SkillRequirement.level(Skill.MINING, 60))))
			.add(TemplateNode.aggregate("B").add(TemplateNode.requirement(SkillRequirement.level(Skill.MINING, 60))));

		TemplateInserter.Result result = TemplateInserter.insert(tree, template);

		// Rot, A, B och ett mining-mål som ligger under både A och B.
		assertEquals(4, tree.size());
		Goal mining = result.getCreated().get(2);
		assertEquals(2, tree.getParents(mining.getId()).size());
		// Ett mål från samma insättning räknas inte som ett inkopplat befintligt mål.
		assertTrue(result.getLinked().isEmpty());
	}

	@Test
	public void excludedNodesAreSkippedWithTheirChildren()
	{
		GoalTree tree = new GoalTree();
		TemplateNode cape = new DiaryCapeTemplate().build(Map.of());
		for (TemplateNode area : cape.getChildren())
		{
			// Hoppa över Elite överallt och hela Wilderness.
			area.getChildren().get(3).setIncluded(false);
			if (area.getTitle().startsWith("Wilderness"))
			{
				area.setIncluded(false);
			}
		}

		TemplateInserter.insert(tree, cape);

		assertEquals(1 + 11 + 11 * 3, tree.size());
		for (Goal goal : tree.flatten())
		{
			if (goal.getRequirement() instanceof DiaryRequirement)
			{
				DiaryRequirement diary = (DiaryRequirement) goal.getRequirement();
				assertFalse(diary.getTier() == DiaryTier.ELITE);
				assertFalse(diary.getArea() == DiaryArea.WILDERNESS);
			}
		}
	}

	@Test
	public void templateRootIsANewCollapsedRootGoal()
	{
		GoalTree tree = new GoalTree();
		tree.add(null, new Goal("Existing"));

		TemplateInserter.Result result = TemplateInserter.insert(tree, new DiaryCapeTemplate().build(Map.of()));

		assertEquals(2, tree.getRootIds().size());
		assertEquals(result.getRoot().getId(), tree.getRootIds().get(1));
		for (Goal goal : result.getCreated())
		{
			if (goal.isAggregate())
			{
				assertFalse(goal.isExpanded());
			}
		}
		assertTrue(result.getRoot().isAggregate());
	}
}

package com.gielinorgoals.template;

import com.gielinorgoals.model.GameData;
import com.gielinorgoals.model.Goal;
import com.gielinorgoals.model.GoalTree;
import com.gielinorgoals.model.QuestRequirement;
import com.google.gson.Gson;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TemplatePlannerTest
{
	@Test
	public void planMatchesWhatInsertDoes()
	{
		GoalTree tree = new GoalTree();
		Goal cooks = new Goal("");
		cooks.setRequirement(new QuestRequirement(Quest.COOKS_ASSISTANT.getId(), "Cook's Assistant"));
		cooks.markCompleted(true, 1L);
		tree.add(null, cooks);
		TemplateNode cape = new QuestCapeTemplate(QuestCapeExclusions.load(new Gson())).build(Map.of());
		cape.getChildren().get(5).setIncluded(false);
		GameData data = finished(Set.of(Quest.DEMON_SLAYER.getId(), Quest.COOKS_ASSISTANT.getId()));

		TemplatePlanner.Plan plan = TemplatePlanner.plan(tree, cape, data);
		TemplateInserter.Result result = TemplateInserter.insert(tree, cape);

		assertEquals(result.getCreated().size() - 1, plan.getNewGoals());
		assertEquals(result.getLinked().size(), plan.getLinkedGoals());
		assertEquals(1, plan.getLinkedGoals());
		// Cook's Assistant (inkopplat och klart) och Demon Slayer (nytt men redan klart).
		assertEquals(2, plan.getAlreadyDone());
		assertEquals(cape.getChildren().size() - 2, plan.getNewGoals());
		assertEquals("Adds 1 root goal, " + plan.getNewGoals() + " new sub-goals, links 1 existing, 2 already done",
			plan.summary());
	}

	@Test
	public void statusesForLinkedSkippedAndDuplicateNodes()
	{
		GoalTree tree = new GoalTree();
		Goal rfd = new Goal("");
		rfd.setRequirement(new QuestRequirement(Quest.RECIPE_FOR_DISASTER.getId(), "Recipe for Disaster"));
		tree.add(null, rfd);
		TemplateNode gloves = HandpickedTemplatesTest.barrowsGloves().build(Map.of());
		TemplateNode rfdNode = gloves.getChildren().get(0);
		TemplateNode skills = gloves.getChildren().get(2);
		skills.getChildren().get(0).setIncluded(false);

		TemplatePlanner.Plan plan = TemplatePlanner.plan(tree, gloves, GameData.EMPTY);

		assertEquals(TemplatePlanner.Status.NEW, plan.statusOf(gloves));
		assertEquals(TemplatePlanner.Status.LINKED, plan.statusOf(rfdNode));
		// Det inkopplade målet behåller sina egna delmål, så templatens delquests läggs inte till.
		assertEquals(TemplatePlanner.Status.SKIPPED, plan.statusOf(rfdNode.getChildren().get(0)));
		assertEquals(TemplatePlanner.Status.SKIPPED, plan.statusOf(skills.getChildren().get(0)));
		assertEquals(TemplatePlanner.Status.NEW, plan.statusOf(skills.getChildren().get(1)));
		// QP-målet och skill-gruppen med 12 kvar.
		assertEquals(1 + 1 + 12, plan.getNewGoals());
	}

	@Test
	public void duplicateInsideTemplateIsMarked()
	{
		TemplateNode root = TemplateNode.aggregate("Root")
			.add(TemplateNode.requirement(new QuestRequirement(17, "Cook's Assistant")))
			.add(TemplateNode.requirement(new QuestRequirement(17, "Cook's Assistant")));

		TemplatePlanner.Plan plan = TemplatePlanner.plan(new GoalTree(), root, GameData.EMPTY);

		assertEquals(TemplatePlanner.Status.NEW, plan.statusOf(root.getChildren().get(0)));
		assertEquals(TemplatePlanner.Status.DUPLICATE, plan.statusOf(root.getChildren().get(1)));
		assertEquals(1, plan.getNewGoals());
	}

	@Test
	public void counterIsDoneWhenAllIncludedChildrenAre()
	{
		TemplateNode base = new BaseLevelTemplate().build(Map.of("level", 50));
		GameData data = skill -> skill == Skill.SAILING ? 0 : 13_034_431L;

		TemplatePlanner.Plan plan = TemplatePlanner.plan(new GoalTree(), base, data);
		assertFalse(plan.isDone(base));

		// Utan Sailing är resten klart, och då räknas räknarmålet som klart.
		for (TemplateNode child : base.getChildren())
		{
			if (child.getDisplayTitle().contains("Sailing"))
			{
				child.setIncluded(false);
			}
		}
		assertTrue(TemplatePlanner.plan(new GoalTree(), base, data).isDone(base));
	}

	private static GameData finished(Set<Integer> questIds)
	{
		return new GameData()
		{
			@Override
			public long getXp(Skill skill)
			{
				return -1;
			}

			@Override
			public QuestState getQuestState(int questId)
			{
				return questIds.contains(questId) ? QuestState.FINISHED : QuestState.NOT_STARTED;
			}
		};
	}
}

package com.gielinorgoals.template;

import com.gielinorgoals.model.DiaryArea;
import com.gielinorgoals.model.DiaryRequirement;
import com.gielinorgoals.model.DiaryTier;
