		assertEquals(List.of("Dragon pickaxe", "Dragon pickaxe (or)"), names);

		assertEquals(List.of("Pickaxe handle", "Dragon pickaxe (or)", "Dragon pickaxe"),
			names(ItemSearch.filter(INDEX, "pickaxe")));
	}

	@Test
	public void resultsAreCapped()
	{
